import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand

__author__ = 'Julia Patacz'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'julia.patacz@nokia.com'


class BtsConnectionStatus(GenericEMSSIMCommand):
    """Btsconnectionstatus command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Btsconnectionstatus command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(BtsConnectionStatus, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "bts_connection_status"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_status_value(line)
                self._parse_bts_info(line)
            except ParsingDone:
                pass
        return super(BtsConnectionStatus, self).on_new_line(line, is_full_line)

    # 09:02:46          |BTS is connected
    _re_bts_info = re.compile(r"(?P<BTS_INFO>BTS.*)")

    def _parse_bts_info(self, line):
        if self._regex_helper.search_compiled(BtsConnectionStatus._re_bts_info, line):
            self.current_ret['bts_info'] = self._regex_helper.group("BTS_INFO")
            raise ParsingDone

    # 09:02:46          | connection_status : 1
    _re_status_value = re.compile(r"\s+(?P<STATUS>\S+)\s+:\s+(?P<VALUE>\S+)$")

    def _parse_status_value(self, line):
        if self._regex_helper.search_compiled(BtsConnectionStatus._re_status_value, line):
            self.current_ret[self._regex_helper.group("STATUS")] = self._regex_helper.group("VALUE")
            raise ParsingDone


